package com.fleettrack.location;

import java.time.Instant;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * One row per location ping (append-only history). The {@code location geography} column is
 * generated by the database. {@code courierId} is a plain column rather than a @ManyToOne:
 * this is a high-volume table and nothing here needs the Courier object.
 */
@Entity
@Table(name = "courier_locations")
public class CourierLocation {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "courier_id", nullable = false)
    private Long courierId;

    @Column(nullable = false)
    private double latitude;

    @Column(nullable = false)
    private double longitude;

    @Column(name = "speed_kmh")
    private Double speedKmh;

    @Column(name = "heading_degrees")
    private Double headingDegrees;

    @Column(name = "recorded_at", nullable = false)
    private Instant recordedAt;

    @Column(name = "received_at", nullable = false)
    private Instant receivedAt;

    protected CourierLocation() {
        // for JPA
    }

    public CourierLocation(Long courierId, double latitude, double longitude, Double speedKmh,
                           Double headingDegrees, Instant recordedAt, Instant receivedAt) {
        this.courierId = courierId;
        this.latitude = latitude;
        this.longitude = longitude;
        this.speedKmh = speedKmh;
        this.headingDegrees = headingDegrees;
        this.recordedAt = recordedAt;
        this.receivedAt = receivedAt;
    }

    public Long getId() {
        return id;
    }

    public Long getCourierId() {
        return courierId;
    }

    public double getLatitude() {
        return latitude;
    }

    public double getLongitude() {
        return longitude;
    }

    public Double getSpeedKmh() {
        return speedKmh;
    }

    public Double getHeadingDegrees() {
        return headingDegrees;
    }

    public Instant getRecordedAt() {
        return recordedAt;
    }

    public Instant getReceivedAt() {
        return receivedAt;
    }
}
